        '<b>Ctrl+Shift+Alt+O</b> xuyên thấu · <b>Ctrl+Shift+Alt+W</b> nhấp xuyên qua · <b>Ctrl+Shift+Alt+B</b> buddy · <b>Ctrl+Shift+Alt+M</b> chọn màn hình',
